};

// Smart selection: balance across categories
function smartSelection(categories, totalLimit) {
  const results = [];
  const categoryNames = Object.keys(categories);
  const storePerCategory = Math.ceil(totalLimit / categoryNames.length);

  // Shuffle categories for randomness
  const shuffledCats = categoryNames.sort(() => Math.random() - 0.5);

  shuffledCats.forEach(catName => {
    const items = categories[catName];
    const shuffled = items.sort(() => Math.random() - 0.5);
    const selected = shuffled.slice(0, storePerCategory);

    selected.forEach(name => {
      if (results.length < totalLimit) {
        results.push({
          store_url: `https://${name}.myshopify.com`,
          store_name: name,
          discovery_method: 'smart_category_selection',
          category: catName
        });
      }
    });
  });

  return results;
}

// Performance tracking
console.log('========== ENHANCED SHOPIFY STORE AUTO-DISCOVERY ==========');
console.log(`Total categories: ${Object.keys(commonStoreNames).length}`);
console.log(`Total patterns: ${Object.values(commonStoreNames).reduce((s, arr) => s + arr.length, 0)}`);

const storeList = smartSelection(commonStoreNames, 80);

console.log(`Generated ${storeList.length} optimized candidate stores`);
console.log(`Discovery method: Smart category-balanced selection`);
console.log(`Expected valid stores: ~${Math.ceil(storeList.length * 0.35)}-${Math.ceil(storeList.length * 0.45)}`);
console.log(`==========================================================`);

return storeList.map(store => ({
  json: store
}));

