// Enhanced: Advanced error classification and validation
// Categorizes failures for intelligent retry and logging

const items = $input.all();
const errorStats = {
  total: items.length,
  valid: 0,
  temporary_errors: 0,  // 429, 503, timeouts
  permanent_errors: 0,  // 404, 403, etc
  network_errors: 0,    // DNS, connection
  empty_response: 0,
  parse_errors: 0
};

const validStores = [];
const failedStores = [];

items.forEach(item => {
  try {
    const storeData = item.json;
    const statusCode = item.json.statusCode || 0;
    const body = item.json.body;
    const errorMsg = item.json.error?.message || '';

    // Classify errors
    let errorType = null;
    let shouldRetry = false;

    if (statusCode === 0 || statusCode === 999) {
      // Network error (timeout, DNS, connection)
      errorStats.network_errors++;
      errorType = 'NETWORK_ERROR';
      shouldRetry = true;
    } else if (statusCode >= 500) {
      // Server error - temporary
      errorStats.temporary_errors++;
      errorType = 'SERVER_ERROR';
      shouldRetry = true;
    } else if (statusCode === 429) {
      // Rate limited - temporary
      errorStats.temporary_errors++;
      errorType = 'RATE_LIMIT';
      shouldRetry = true;
    } else if (statusCode === 404 || statusCode === 403) {
      // Not found or forbidden - permanent
      errorStats.permanent_errors++;
      errorType = 'NOT_FOUND';
      shouldRetry = false;
    } else if (!body || body.length === 0) {
      // Empty response
      errorStats.empty_response++;
      errorType = 'EMPTY_RESPONSE';
      shouldRetry = false;
    } else if (statusCode >= 400) {
      // Other client errors
      errorStats.permanent_errors++;
      errorType = 'CLIENT_ERROR';
      shouldRetry = false;
    } else if (statusCode >= 200 && statusCode < 400) {
      // Success!
      errorStats.valid++;
      const homepageContent = typeof body === 'string' ? body : JSON.stringify(body);

      validStores.push({
        json: {
          store_url: storeData.store_url,
          store_name: storeData.store_name,
          homepage_content: homepageContent,
          statusCode: statusCode,
          scraped_pages: ['homepage'],
          scraped_at: new Date().toISOString(),
          quality_score: Math.min(100, Math.max(50, (homepageContent.length / 100)))
        }
      });
    }

    // Track failed stores
    if (statusCode >= 400 || !body) {
      failedStores.push({
        store_url: storeData.store_url,
        store_name: storeData.store_name,
        error_type: errorType,
        status_code: statusCode,
        should_retry: shouldRetry,
        timestamp: new Date().toISOString()
      });
    }

  } catch (error) {
    errorStats.parse_errors++;
    failedStores.push({
      store_url: item.json?.store_url || 'unknown',
      error_type: 'PARSE_ERROR',
      error_message: error.message
    });
  }
});

// Log statistics
console.log('\n========== ADVANCED STORE VALIDATION ==========');
console.log(`Total stores tested: ${errorStats.total}`);
console.log(`Valid stores: ${errorStats.valid} (${((errorStats.valid/errorStats.total)*100).toFixed(2)}%)`);
console.log(`\nError Breakdown:`);
console.log(`  - Temporary errors (retry): ${errorStats.temporary_errors}`);
console.log(`  - Permanent errors: ${errorStats.permanent_errors}`);
console.log(`  - Network errors: ${errorStats.network_errors}`);
console.log(`  - Empty responses: ${errorStats.empty_response}`);
console.log(`  - Parse errors: ${errorStats.parse_errors}`);

if (failedStores.length > 0 && failedStores.length <= 5) {
  console.log(`\nSample failed stores:`);
  failedStores.slice(0, 5).forEach(s => {
    console.log(`  - ${s.store_url}: ${s.error_type} (retry: ${s.should_retry})`);
  });
}

console.log(`============================================\n`);

return validStores;

