// Find contact page URLs from common Shopify paths
const items = $input.all();

return items.map(item => {
  const storeUrl = item.json.store_url;

  try {
    // Extract base URL
    const urlObj = new URL(storeUrl);
    const baseUrl = `${urlObj.protocol}//${urlObj.host}`;

    // Common contact page paths on Shopify stores
    const contactPaths = [
      '/pages/contact',
      '/pages/contact-us',
      '/contact',
      '/contact-us',
      '/pages/about',
      '/pages/support',
      '/support',
      '/help',
      '/pages/locations',
      '/locations',
      '/pages/faq',
      '/faq'
    ];

    const contact_urls = contactPaths.map(path => baseUrl + path);

    return {
      json: {
        store_url: item.json.store_url,
        store_name: item.json.store_name,
        homepage_content: item.json.homepage_content,
        contact_urls: contact_urls,
        scraped_pages: item.json.scraped_pages || [],
        error: item.json.error,
        scraped_at: item.json.scraped_at
      }
    };
  } catch (error) {
    return {
      json: {
        store_url: item.json.store_url,
        store_name: item.json.store_name,
        homepage_content: item.json.homepage_content,
        contact_urls: [],
        error: `Failed to generate contact URLs: ${error.message}`,
        scraped_at: item.json.scraped_at
      }
    };
  }
});

// Prepare batch URLs for scraping - convert array to multiple items
