    // Create one item per contact URL
    contactUrls.forEach((contactUrl, index) => {
      results.push({
        json: {
          store_url: storeUrl,
          store_name: storeName,
          homepage_content: homepageContent,
          url: contactUrl,
          page_type: 'contact_page',
          page_index: index
        }
      });
      totalUrls++;
